Theorem huf_dec_1x_disp :
  dec1_int_stmt x1_tab PHUF_DX1_1X -> dec1_int_stmt x2_tab PHUF_DX2_1X -> huf_dec_stmt huf_dt_ok PHUF_DEC_1X.
Proof.
  intros H1 H2. unfold huf_dec_stmt, PHUF_DEC_1X.
  intros until lo. intros MTL DTOK DSTC DCAP SRC BY SL S16 S0 DT0 DT8 DTL DSTL SL2 J1 J2 J3 STK STKL SP16 SP47 MI FL -> -> -> -> -> ->.
  zstep. zstep. if_cases U; zify_cond U;
    [exfalso; apply U; change 3 with (Z.ones 2); rewrite Z.land_ones by lia; Z.div_mod_to_equations; lia|].
  destruct DTOK as (tt & tl & BD & [(-> & cells & CL & CT & TL & CB) | (-> & cells & CL & CT & TL & CB)]);
    pose proof (desc_tt_rd _ _ _ _ _ BD) as RD.
  - disp_to 87276. eapply H1; try eassumption; try reflexivity.
    exists tl, cells. exact (conj BD (conj CL (conj CT (conj TL CB)))).
  - disp_to 84224. eapply H2; try eassumption; try reflexivity.
    exists tl, cells. exact (conj BD (conj CL (conj CT (conj TL CB)))).
Qed.

